#!/usr/bin/env python3
"""Extract IQ/K-quant codebook tables from ggml-common.h (MIT, (c) The ggml authors)
into src/quant_tables.inc as plain C arrays usable from both host and device code."""
import re, sys
src = open(sys.argv[1]).read()
names = ["kmask_iq2xs", "ksigns_iq2xs", "iq2xxs_grid", "iq2xs_grid", "iq2s_grid",
         "iq3xxs_grid", "iq3s_grid", "kvalues_iq4nl", "iq1s_grid"]
out = ["// Generated by scripts/gen_tables.py from ggml-common.h (MIT License, Copyright (c) 2023-2026 The ggml authors).",
       "// Codebooks for the GGUF IQ quantization formats. Do not edit.",
       "// Usage: #define QT_DECL(type, name, size) <qualifiers> type name[size] before including.", ""]
for n in names:
    m = re.search(r"GGML_TABLE_BEGIN\((\w+),\s*" + n + r",\s*(\w+)\)(.*?)GGML_TABLE_END\(\)", src, re.S)
    if not m: sys.exit("missing " + n)
    typ, size, body = m.groups()
    if size == "NGRID_IQ1S": size = "2048"
    out.append(f"QT_DECL({typ}, {n}, {size}) = {{{body.strip()}}};")
open(sys.argv[2], "w").write("\n".join(out) + "\n")
print("ok", len(names))
